 "content": "def transform(grid):
    out=[row[:] for row in grid]
    h=len(grid)
    # Find rings by bounding rectangles, replacing their cavities with the ring's partner color.
    for color, fill in ((0,7),(3,2),(5,7),(8,7),(9,2)):
        pts={(r,c) for r in range(h) for c in range(len(grid[r])) if grid[r][c]==color}
        unseen=set(pts)
        while unseen:
            start=unseen.pop(); comp={start}; stack=[start]
            while stack:
                y,x=stack.pop()
                for q in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if q in unseen:
                        unseen.remove(q);comp.add(q);stack.append(q)
            y0=min(y for y,x in comp);y1=max(y for y,x in comp)
            x0=min(x for y,x in comp);x1=max(x for y,x in comp)
            if y1-y0<2 or x1-x0<2: continue
            border={(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1) if y in (y0,y1) or x in (x0,x1)}
            if comp != border: continue
            area=(y1-y0-1)*(x1-x0-1)
            v=7 if area==1 else fill
            for y in range(y0+1,y1):
                for x in range(x0+1,x1): out[y][x]=v
    return out
